import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import ItemList from 'flarum/common/utils/ItemList';
import extractText from 'flarum/common/utils/extractText';
import Avatar from './Avatar';
import Icons from '../icons';
import { activityLine, activityHref } from './activity';
const t = function (key, params) {
  if (params === void 0) {
    params = {};
  }
  return app.translator.trans('ernestdefoe-parley.forum.' + key, params);
};

/**
 * One person in the online list. Click anywhere on the row to message them;
 * hover for the buttons on the right.
 */

export default class PersonRow extends Component {
  view() {
    const p = this.attrs.person;
    const unread = this.attrs.unread || 0;
    const name = p.displayName;
    return m("div", {
      className: 'pl-person' + (p.status === 'offline' ? ' off' : ''),
      tabindex: "0",
      role: "button",
      "aria-label": extractText(t('rail.message_person', {
        name
      })),
      onclick: () => app.parley.openWith(p.id),
      onkeydown: e => {
        if ((e.key === 'Enter' || e.key === ' ') && e.target === e.currentTarget) {
          e.preventDefault();
          app.parley.openWith(p.id);
        }
      }
    }, Avatar(p, 36, {
      dot: true
    }), m("div", {
      className: "pl-info"
    }, m("div", {
      className: "pl-nm"
    }, name, p.badge ? m("span", {
      className: 'pl-badge' + (p.badge.staff ? ' mod' : '')
    }, p.badge.name) : null), m("div", {
      className: "pl-act"
    }, activityLine(p))), unread ? m("span", {
      className: "pl-unread"
    }, unread) : null, m("span", {
      className: "pl-acts",
      onclick: e => e.stopPropagation()
    }, this.actionItems(p).toArray()));
  }

  /**
   * The hover buttons. Parley Calls adds voice and video here and takes the
   * message button away, exactly as the two editions differ in the mockup.
   */
  actionItems(p) {
    const items = new ItemList();
    const href = activityHref(p);

    // In a room you can see: "Go to" opens the room itself.
    if (p.activity && p.activity.roomId) {
      items.add('goto', m("button", {
        className: "pl-ib",
        title: extractText(t('rail.go_to', {
          place: p.activity.label
        })),
        "aria-label": extractText(t('rail.go_to', {
          place: p.activity.label
        })),
        onclick: () => app.parley.openRoom(p.activity.roomId)
      }, Icons.goto()), 100);
    }
    if (href) {
      items.add('goto', m("a", {
        className: "pl-ib",
        href: href,
        title: extractText(t('rail.go_to', {
          place: p.activity.label
        })),
        "aria-label": extractText(t('rail.go_to', {
          place: p.activity.label
        })),
        onclick: e => {
          e.preventDefault();
          m.route.set(href);
        }
      }, Icons.goto()), 100);
    }
    items.add('message', m("button", {
      className: "pl-ib",
      title: extractText(t('rail.message')),
      "aria-label": extractText(t('rail.message_person', {
        name: p.displayName
      })),
      onclick: () => app.parley.openWith(p.id)
    }, Icons.msg()), 0);
    return items;
  }
}
flarum.reg.add('ernestdefoe-parley', 'forum/components/PersonRow', PersonRow);